71	
72	    if (!workbook || !unitId) {
73	        return;
74	    }
75	
76	    const insertConfirm = (param: IDefinedNamesServiceParam) => {
77	        const { name, formulaOrRefString, comment, localSheetId, hidden } = param;
78	
79	        let id = param.id;
80	        if (id == null || id.length === 0) {
81	            id = generateRandomId(10);
82	            commandService.executeCommand(InsertDefinedNameCommand.id, { id, unitId, name, formulaOrRefString, comment, localSheetId, hidden });
83	        } else {
