85	            commandService.executeCommand(SetDefinedNameCommand.id, newDefinedName);
86	        }
87	        setEditState(false);
88	        setEditorKey(null);
89	    };
90	
91	    const deleteDefinedName = (id: string) => {
92	        setDeleteConformKey(id);
93	    };
94	
95	    function handleDeleteClose() {
96	        setDeleteConformKey(null);
97	    }
98	
99	    function handleDeleteConfirm(id: string) {
100	        if (!unitId) return;
101	        const item = definedNamesService.getValueById(unitId, id);
102	        commandService.executeCommand(RemoveDefinedNameCommand.id, { ...item, unitId });
103	        setDeleteConformKey(null);
104	    }
105	
106	    const focusDefinedName = async (definedName: IDefinedNamesServiceParam) => {
107	        // The worksheet may be hidden, so we need to show it first
108	        const { formulaOrRefString, id } = definedName;
109	        const worksheet = definedNamesService.getWorksheetByRef(unitId, formulaOrRefString);
110	        if (!worksheet) {
111	            return;
112	        }
113	
114	        const isHidden = worksheet.isSheetHidden();
115	        if (isHidden) {
116	            await commandService.executeCommand(SetWorksheetShowCommand.id, { unitId, subUnitId: worksheet.getSheetId() });
117	        }
118	
119	        definedNamesService.focusRange(unitId, id);
120	    };
121	
122	    const getInsertDefinedName = () => {
