139	            id,
140	        });
141	
142	        if (typeof validationResult === 'string') {
143	            setValidString(localeService.t(validationResult));
144	            return;
145	        }
146	
147	        if (!validFormulaOrRange) {
148	            setValidString(localeService.t('definedName.formulaOrRefStringInvalid'));
149	            return;
150	        }
151	
152	        const currentSheetName = workbook.getActiveSheet().getName();
153	        confirm && confirm({
154	            id: id || '',
155	            name: nameValue,
156	            formulaOrRefString: lexerTreeBuilder.convertRefersToAbsolute(formulaOrRefStringValue, AbsoluteRefType.ALL, AbsoluteRefType.ALL, currentSheetName),
