163	        const type = value as string;
164	        if (type === 'formula') {
165	            if (formulaOrRefString[0] === operatorToken.EQUALS) {
166	                setFormulaOrRefStringValue(formulaOrRefString);
167	            } else {
168	                setFormulaOrRefStringValue(`${operatorToken.EQUALS}`);
169	            }
170	        } else {
171	            if (formulaOrRefString[0] === operatorToken.EQUALS) {
172	                setFormulaOrRefStringValue('');
173	            } else {
174	                setFormulaOrRefStringValue(formulaOrRefString);
175	            }
176	        }
177	        setTypeValue(type);
178	    };
179	
180	    const formulaEditorRef = useRef<any>(null);
181	    const [isFocusFormulaEditor, setIsFocusFormulaEditor] = useState(false);
182	
183	    useSidebarClick((e: MouseEvent) => {
184	        const isOutSide = formulaEditorRef.current?.isClickOutSide(e);
185	        isOutSide && setIsFocusFormulaEditor(false);
186	    });
187	
188	    return (
189	        <div
190	            className={clsx('univer-grid univer-space-y-2 univer-pb-1', borderBottomClassName, {
191	                'univer-hidden': !state,
192	            })}
193	        >
194	            <div>
